/* ICM_SYS_AXI_IC_AXI_IC_REG_DEC_FAILURE_CAUSE : RO ;bitpos:[5:3] ;default: 3'd0 ; */
/*description: bit[0] is 0 means to access the mapped slave address, and is 1 means to access t
he unmapped slave address. bit[1] is 0 means to access the visiable slave, and i
s 1 means to access the invisible slave. bit[2] is 0 means to access the secure
slave, and is 1 means to access the non-secure slave..*/
#define ICM_SYS_AXI_IC_AXI_IC_REG_DEC_FAILURE_CAUSE    0x00000007
#define ICM_SYS_AXI_IC_AXI_IC_REG_DEC_FAILURE_CAUSE_M  ((ICM_SYS_AXI_IC_AXI_IC_REG_DEC_FAILURE_CAUSE_V)<<(ICM_SYS_AXI_IC_AXI_IC_REG_DEC_FAILURE_CAUSE_S))
