#define ICM_SYS_AXI_IC_AXI_IC_REG_DEC_FAILURE_VALID_M  (BIT(1))
#define ICM_SYS_AXI_IC_AXI_IC_REG_DEC_FAILURE_VALID_V  0x1
#define ICM_SYS_AXI_IC_AXI_IC_REG_DEC_FAILURE_VALID_S  1
/* ICM_SYS_AXI_IC_AXI_IC_REG_DEC_FAILURE_READ_FIRST : R/W ;bitpos:[0] ;default: 1'd0 ; */
/*description: Decoder failure recorded control. 1 means record read failure first, else write
failure first..*/
#define ICM_SYS_AXI_IC_AXI_IC_REG_DEC_FAILURE_READ_FIRST    (BIT(0))
#define ICM_SYS_AXI_IC_AXI_IC_REG_DEC_FAILURE_READ_FIRST_M  (BIT(0))
